const fs = require('fs');
const path = require('path');

const questions = [];

function addQ(category, question, options, correctIndex, explanation) {
  questions.push({
    id: `q${questions.length + 1}`,
    category,
    question,
    options,
    correctIndex,
    explanation,
  });
}

